<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';import {request} from '@/integration/service';import ImagePicker from '@/integration/ImagePicker.vue';
const form=ref(null),tab=ref('home'),busy=ref(false),message=ref(''),draftImage=ref(''),dirty=ref(false);
const tabs=[['home','首页海报'],['style','博客外观'],['info','基本信息']];
const imageUrl=v=>v?.startsWith('/')?v:'/assets/'+(v||'landscape-fields')+'.webp';
const preview=computed(()=>imageUrl(form.value?.heroImages?.[0]));
onMounted(async()=>{try{form.value=await request('/api/admin/site');if(form.value.heroTail==='的随记')form.value.heroTail='';}catch(e){message.value=e.message;}});
function addImage(){if(!draftImage.value)return;if(form.value.heroImages.length>=6){message.value='最多保留 6 张海报，请先移除一张';return;}if(!form.value.heroImages.map(imageUrl).includes(draftImage.value)){form.value.heroImages.push(draftImage.value);dirty.value=true;}draftImage.value='';}
function move(i,d){const list=form.value.heroImages;if(i+d<0||i+d>=list.length)return;[list[i],list[i+d]]=[list[i+d],list[i]];dirty.value=true;}
async function save(){busy.value=true;message.value='';try{form.value=await request('/api/admin/site','PUT',form.value);dirty.value=false;message.value='已保存，公开博客刷新后生效';}catch(e){message.value=e.message;}finally{busy.value=false;}}
</script>
<template><section class="site-settings-v8"><header class="settings-intro"><div><span class="space-eyebrow">THE PUBLIC SIDE</span><h1>给博客换个表情。</h1><p>这里的设置会公开展示。私人空间的壁纸与角色在空间外观中调整。</p></div><a href="/" target="_blank" rel="noopener">查看博客 ↗</a></header><nav class="settings-tabs" aria-label="博客设置分组"><button v-for="[id,label] in tabs" :key="id" type="button" :aria-pressed="tab===id" @click="tab=id">{{label}}</button></nav><form v-if="form" @submit.prevent="save" @input="dirty=true" @change="dirty=true"><div class="settings-columns"><div class="settings-fields"><section v-show="tab==='home'" class="settings-panel"><h2>首页海报</h2><label>首屏布局<el-radio-group v-model="form.heroMode"><el-radio-button value="poster">整屏海报</el-radio-button><el-radio-button value="collage">拼贴手记</el-radio-button></el-radio-group></label><div class="hero-sequence"><h3>轮播顺序 <small>{{form.heroImages.length}} / 6</small></h3><div v-for="(img,i) in form.heroImages" :key="img" class="hero-sequence-item"><img :src="imageUrl(img)" alt="海报预览"/><span>第 {{i+1}} 张</span><button type="button" :disabled="i===0" :aria-label="'上移第'+(i+1)+'张'" @click="move(i,-1)">↑</button><button type="button" :disabled="i===form.heroImages.length-1" :aria-label="'下移第'+(i+1)+'张'" @click="move(i,1)">↓</button><button type="button" :disabled="form.heroImages.length<=1" :aria-label="'移除第'+(i+1)+'张'" @click="form.heroImages.splice(i,1);dirty=true">移除</button></div></div><details class="add-poster"><summary>＋ 添加海报</summary><ImagePicker v-model="draftImage" label="海报图片"/><el-button :disabled="!draftImage||form.heroImages.length>=6" @click="addImage">加入轮播</el-button></details><div class="settings-two"><label>轮换间隔（秒）<el-input-number v-model="form.heroInterval" :min="3" :max="60"/></label><label>遮罩强度<el-slider v-model="form.heroOverlay" :min="0" :max="80"/></label></div><label>小标签<el-input v-model="form.heroLabel" maxlength="60"/></label><label>主标题<el-input v-model="form.heroTitle" maxlength="60" placeholder="留空使用网站名称"/></label><label>第二行（可留空）<el-input v-model="form.heroTail" maxlength="20"/></label><label>海报文案<el-input v-model="form.heroIntro" maxlength="120" placeholder="留空使用博客简介"/></label><label>滚动提示<el-input v-model="form.scrollCue" maxlength="16"/></label></section><section v-show="tab==='style'" class="settings-panel"><h2>博客外观</h2><label>色彩与质感<el-radio-group v-model="form.blogTheme"><el-radio-button value="paper">纸页 · 暖色手记</el-radio-button><el-radio-button value="gallery">画廊 · 清透蓝灰</el-radio-button></el-radio-group></label><label>文章列表<el-radio-group v-model="form.listStyle"><el-radio-button value="editorial">横向阅读列表</el-radio-button><el-radio-button value="grid">双列封面卡片</el-radio-button></el-radio-group></label><div class="settings-switches"><label><el-switch v-model="form.motion"/>页面动效与轮播</label><label><el-switch v-model="form.showTicker"/>首页滚动文字带</label><label><el-switch v-model="form.showSidebar"/>首页站主侧栏</label><label><el-switch v-model="form.previewImages"/>侧栏背景点击预览</label></div><h3>博客页面背景</h3><ImagePicker v-model="form.blogBackground" label="博客背景"/><h3>内页标题背景</h3><ImagePicker v-model="form.coverImage" label="内页背景"/><h3>侧栏名片背景</h3><ImagePicker v-model="form.avatarBg" label="名片背景" :clearable="false"/></section><section v-show="tab==='info'" class="settings-panel"><h2>基本信息</h2><label>网站名称<el-input v-model="form.title" maxlength="80" required/></label><label>博客简介<el-input v-model="form.subtitle" maxlength="160" type="textarea" :rows="3"/></label><label>公告<el-input v-model="form.notice" type="textarea" maxlength="500" :rows="4"/></label><label class="settings-inline"><el-switch v-model="form.commentsEnabled"/>接收新评论</label><p>所有评论经你审核后才会展示。</p><RouterLink to="/profile">修改站主头像与简介 →</RouterLink></section></div><aside class="settings-preview" :data-look="form.blogTheme"><div class="preview-top"><b>{{form.title}}</b><span>随手记 · 说说 · 相册</span></div><div class="preview-poster" :style="{backgroundImage:'linear-gradient(#101c28'+Math.round(form.heroOverlay*2.55).toString(16).padStart(2,'0')+',#101c2870),url('+preview+')'}"><span>{{form.heroLabel}}</span><strong>{{form.heroTitle||form.title}}</strong><em>{{form.heroTail}}</em><p>{{form.heroIntro||form.subtitle}}</p></div><div class="preview-articles" :class="{grid:form.listStyle==='grid'}"><div v-for="n in 2" :key="n"><i/><span>日常里，值得记住的一页。</span></div></div><small>外观预览 · 保存后应用到公开博客</small></aside></div><footer class="settings-save"><span role="status">{{message||(dirty?'有尚未保存的修改':'')}}</span><el-button type="primary" native-type="submit" :loading="busy">保存博客设置</el-button></footer></form><p v-else role="status">{{message||'正在读取设置…'}}</p></section></template>
<style scoped>.site-settings-v8{max-width:1250px;margin:auto}.settings-intro{display:flex;justify-content:space-between;align-items:center;gap:20px}.settings-intro h1{font-size:31px;margin:12px 0}.settings-intro p,.settings-panel p{font-size:12px;line-height:1.8;color:var(--studio-muted)}.settings-intro>a{white-space:nowrap;font-size:12px}.settings-tabs{display:flex;gap:8px;margin:26px 0 22px}.settings-tabs button{border:1px solid var(--studio-line);border-radius:6px;padding:10px 18px;background:var(--studio-panel);color:inherit;font-size:13px;cursor:pointer}.settings-tabs button[aria-pressed=true]{background:#7e6b92;color:white}.settings-columns{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(260px,1fr);gap:25px;align-items:start}.settings-panel{border:1px solid var(--studio-line);background:var(--studio-panel);border-radius:12px;padding:26px}.settings-panel h2{font-size:21px;margin:0 0 25px}.settings-panel h3{font-size:15px;margin:27px 0 16px}.settings-panel>label,.settings-two>label{display:flex;flex-direction:column;gap:10px;margin:20px 0;font-size:12px}.settings-panel a{font-size:12px;display:block;margin-top:25px}.settings-two{display:grid;grid-template-columns:1fr 1fr;gap:25px}.hero-sequence-item{display:flex;gap:9px;align-items:center;margin:10px 0;padding:8px;background:var(--studio-bg);border-radius:6px}.hero-sequence-item img{width:84px;height:48px;object-fit:cover;border-radius:4px}.hero-sequence-item span{font-size:11px;margin-right:auto}.hero-sequence-item button{border:1px solid var(--studio-line);border-radius:4px;padding:5px 8px;background:var(--studio-panel);color:inherit;font-size:11px;cursor:pointer}.hero-sequence-item button:disabled{opacity:.35;cursor:default}.hero-sequence h3 small{float:right;font-weight:400}.add-poster{border:1px dashed var(--studio-line);padding:14px;border-radius:8px;margin:20px 0}.add-poster summary{font-size:12px;cursor:pointer}.add-poster[open] summary{margin-bottom:18px}.add-poster .el-button{margin-top:15px}.settings-switches{display:grid;grid-template-columns:1fr;gap:15px;margin:28px 0}.settings-switches label,.settings-panel .settings-inline{display:flex;flex-direction:row;align-items:center;gap:12px;font-size:12px}.settings-preview{position:sticky;top:110px;border-radius:12px;border:1px solid var(--studio-line);overflow:hidden;background:#faf8f1;color:#3e493f;box-shadow:0 12px 35px #27314b0a}.settings-preview[data-look=gallery]{background:#edf3f8;color:#344f69}.preview-top{display:flex;justify-content:space-between;align-items:center;padding:15px;gap:10px}.preview-top b{font-size:12px}.preview-top span{font-size:8px}.preview-poster{background-position:center;background-size:cover;padding:45px 20px;color:white;text-align:center;min-height:225px}.preview-poster>span{font-size:7px;letter-spacing:2px}.preview-poster strong{display:block;font-size:23px;margin:17px 0 7px}.preview-poster em{font-style:normal;font-size:12px}.preview-poster p{font-size:9px;line-height:1.8;margin-top:15px}.preview-articles{padding:20px;display:grid;gap:12px}.preview-articles>div{display:flex;align-items:center;gap:10px;font-size:9px;border-bottom:1px solid #d9dfe0;padding-bottom:12px}.preview-articles i{display:block;width:70px;height:45px;background:#c9d4cc}.preview-articles.grid{grid-template-columns:1fr 1fr}.preview-articles.grid>div{display:block}.preview-articles.grid i{width:100%;height:65px;margin-bottom:8px}.settings-preview>small{display:block;text-align:center;padding:8px 15px 18px;font-size:9px;color:#7e8590}.settings-save{position:sticky;bottom:0;z-index:10;display:flex;justify-content:space-between;align-items:center;gap:15px;background:var(--studio-panel);border:1px solid var(--studio-line);border-radius:8px;padding:15px 20px;margin-top:25px;font-size:12px}.settings-fields{min-width:0}@media(max-width:1100px){.settings-columns{grid-template-columns:1fr}.settings-preview{position:static;max-width:600px;width:100%}}@media(max-width:500px){.settings-panel{padding:18px}.settings-intro h1{font-size:25px}.settings-intro{align-items:start}.settings-intro>a{font-size:10px}.settings-tabs{gap:6px}.settings-tabs button{padding:9px 12px;font-size:12px}.settings-two{grid-template-columns:1fr;gap:0}.hero-sequence-item img{width:60px}.hero-sequence-item{gap:6px}.hero-sequence-item button{padding:5px}.settings-save{padding:12px}}
</style>
